base={'before':{},'protected':json.loads((P/'baseline.json').read_text())['protected']}
for n in targets:
 p=R/n;q=O/'before'/n;q.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,q);base['before'][n]=hashlib.sha256(p.read_bytes()).hexdigest()
